-- P02 · Privilégios do DONO HISTÓRICO (P01), lidos do catálogo — v1.0.4 (unaccent INSTALADA/NOVA, dicionário, sem OID fixo). Não prova o executor efetivo.
-- Se o executor efetivo for outro papel, estes resultados não se aplicam a ele: a prova é externa (B2).
-- unaccent: P02-07 classifica INSTALADA (em extensions) ou NOVA (não instalada e disponível). INSTALADA:
-- P02-10/11 (assinaturas, pertença, EXECUTE) e P02-16 (dicionário: pertença, modelo, opções, dono). NOVA:
-- P02-12/13/14 (sem objetos soltos; superutilizador ou trusted + CREATE; privilégios por omissão do dono
-- histórico e do superutilizador de arranque, lido como dono de pg_catalog). O outro estado dá n.a.
-- LIMITE: listas de extensões permitidas e outras camadas da plataforma não aparecem no catálogo; o caminho
-- real do executor do staging continua PENDENTE (B2, B16).
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH ux AS (SELECT e.oid, e.extversion::text AS versao, n.nspname::text AS esquema FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'unaccent'),
ua AS (SELECT v.version::text AS versao, v.trusted, v.superuser FROM pg_available_extension_versions v JOIN pg_available_extensions a ON a.name = v.name AND a.default_version = v.version WHERE v.name = 'unaccent'),
est AS (SELECT CASE WHEN (SELECT count(*) FROM ux) = 1 AND (SELECT esquema FROM ux) = 'extensions' THEN 'INSTALADA' WHEN (SELECT count(*) FROM ux) = 1 THEN 'INSTALADA NOUTRO SCHEMA' WHEN (SELECT count(*) FROM ua) = 1 THEN 'NOVA' ELSE 'INDISPONÍVEL' END AS estado),
uf AS (SELECT to_regprocedure('extensions.unaccent(regdictionary, text)') AS f2, to_regprocedure('extensions.unaccent(text)') AS f1),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'P02-01'::text, 'dono histórico identificado'::text, ((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')) IS NOT NULL)::boolean, 'papel'::text, (pg_get_userbyid((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')))::text)::text
  UNION ALL SELECT 'P02-02'::text, 'CREATE no schema public'::text, (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'public', 'CREATE'))::boolean, 'sim'::text, (has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'public', 'CREATE')::text)::text
  UNION ALL SELECT 'P02-03'::text, 'USAGE no schema auth e EXECUTE em auth.uid() (barreira e políticas)'::text, (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR (has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth', 'USAGE') AND has_function_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth.uid()', 'EXECUTE')))::boolean, 'sim'::text, (has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth', 'USAGE')::text || '/' || has_function_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth.uid()', 'EXECUTE')::text)::text
  UNION ALL SELECT 'P02-04'::text, 'REFERENCES em auth.users (só profiles_id_fkey)'::text, (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR has_table_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth.users', 'REFERENCES'))::boolean, 'sim'::text, (has_table_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'auth.users', 'REFERENCES')::text || ' (dono auth.users = ' || coalesce((SELECT pg_get_userbyid(relowner)::text FROM pg_class WHERE oid = 'auth.users'::regclass), '?') || ')')::text
  UNION ALL SELECT 'P02-05'::text, 'dono (ou membro do dono) de public.app_role (ADD VALUE)'::text, (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR coalesce((SELECT ((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')) = t.typowner OR pg_has_role((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), t.typowner, 'MEMBER')) FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'), false))::boolean, 'sim'::text, ((SELECT pg_get_userbyid(t.typowner)::text FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'))::text
  UNION ALL SELECT 'P02-06'::text, 'BYPASSRLS ou superutilizador (8 tabelas com FORCE RLS escritas por funções SECURITY DEFINER do dono)'::text, (coalesce((SELECT rolbypassrls OR rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false))::boolean, 'sim'::text, ((SELECT 'bypassrls=' || rolbypassrls::text || ', super=' || rolsuper::text FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))))::text
  UNION ALL SELECT 'P02-07'::text, 'unaccent: estado discriminado = INSTALADA (em extensions) ou NOVA (não instalada; versão por omissão disponível). INSTALADA NOUTRO SCHEMA ou INDISPONÍVEL => FALHA (o S4-00 usa IF NOT EXISTS e o S4-01 chama extensions.unaccent)'::text, ((SELECT estado FROM est) IN ('INSTALADA', 'NOVA'))::boolean, 'INSTALADA ou NOVA'::text, ((SELECT estado FROM est) || coalesce(' v' || (SELECT versao FROM ux) || ' em ' || (SELECT esquema FROM ux), '') || coalesce(' / disponível v' || (SELECT versao FROM ua) || ' trusted=' || (SELECT trusted::text FROM ua) || ' superuser=' || (SELECT superuser::text FROM ua), ' / sem versão disponível'))::text
  UNION ALL SELECT 'P02-08'::text, 'service_role com USAGE em extensions (colunas geradas usam extensions.unaccent)'::text, (has_schema_privilege('service_role', 'extensions', 'USAGE'))::boolean, 'sim'::text, (has_schema_privilege('service_role', 'extensions', 'USAGE')::text)::text
  UNION ALL SELECT 'P02-09'::text, 'papéis anon, authenticated e service_role existem'::text, ((SELECT count(*) FROM pg_roles WHERE rolname IN ('anon', 'authenticated', 'service_role')) = 3)::boolean, '3'::text, ((SELECT count(*) FROM pg_roles WHERE rolname IN ('anon', 'authenticated', 'service_role'))::text)::text
  UNION ALL SELECT 'P02-10'::text, 'só INSTALADA (n.a. se NOVA): assinaturas extensions.unaccent(regdictionary, text) e extensions.unaccent(text) devolvem text, pertencem à extensão, e o dicionário extensions.unaccent existe'::text, ((SELECT estado FROM est) = 'NOVA' OR ((SELECT f2 FROM uf) IS NOT NULL AND (SELECT f1 FROM uf) IS NOT NULL AND (SELECT bool_and(p.prorettype = 'text'::regtype) FROM pg_proc p WHERE p.oid IN ((SELECT f1 FROM uf), (SELECT f2 FROM uf))) AND (SELECT count(*) FROM pg_depend d WHERE d.classid = 'pg_proc'::regclass AND d.objid IN ((SELECT f1 FROM uf), (SELECT f2 FROM uf)) AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e') = 2 AND EXISTS (SELECT 1 FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')))::boolean, 'sim (INSTALADA) · n.a. (NOVA)'::text, (CASE WHEN (SELECT estado FROM est) = 'NOVA' THEN 'n.a. (NOVA)' ELSE 'f(regdictionary,text)=' || coalesce((SELECT f2 FROM uf)::text, 'em falta') || ' f(text)=' || coalesce((SELECT f1 FROM uf)::text, 'em falta') || ' membros da extensão=' || (SELECT count(*) FROM pg_depend d WHERE d.classid = 'pg_proc'::regclass AND d.objid IN ((SELECT f1 FROM uf), (SELECT f2 FROM uf)) AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e')::text || ' dicionário=' || EXISTS (SELECT 1 FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')::text END)::text
  UNION ALL SELECT 'P02-11'::text, 'só INSTALADA (n.a. se NOVA): service_role (colunas geradas via public.text_norm) e o dono histórico com EXECUTE em extensions.unaccent(regdictionary, text)'::text, ((SELECT estado FROM est) = 'NOVA' OR (has_function_privilege('service_role', (SELECT f2 FROM uf), 'EXECUTE') AND (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR has_function_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), (SELECT f2 FROM uf), 'EXECUTE'))))::boolean, 'sim (INSTALADA) · n.a. (NOVA)'::text, (CASE WHEN (SELECT estado FROM est) = 'NOVA' THEN 'n.a. (NOVA)' ELSE 'service_role=' || coalesce(has_function_privilege('service_role', (SELECT f2 FROM uf), 'EXECUTE')::text, 'NULL') || ' dono=' || coalesce(has_function_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), (SELECT f2 FROM uf), 'EXECUTE')::text, 'NULL') END)::text
  UNION ALL SELECT 'P02-12'::text, 'só NOVA (n.a. se INSTALADA): nenhum objeto solto unaccent/unaccent_init/unaccent_lexize, dicionário ou modelo unaccent em extensions (o CREATE EXTENSION colidiria)'::text, ((SELECT estado FROM est) = 'INSTALADA' OR ((SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'extensions' AND p.proname IN ('unaccent', 'unaccent_init', 'unaccent_lexize')) + (SELECT count(*) FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent') + (SELECT count(*) FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent')) = 0)::boolean, '0 (NOVA) · n.a. (INSTALADA)'::text, (CASE WHEN (SELECT estado FROM est) = 'INSTALADA' THEN 'n.a. (INSTALADA)' ELSE ((SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'extensions' AND p.proname IN ('unaccent', 'unaccent_init', 'unaccent_lexize')) + (SELECT count(*) FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent') + (SELECT count(*) FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent'))::text END)::text
  UNION ALL SELECT 'P02-13'::text, 'só NOVA (n.a. se INSTALADA): o dono histórico pode criar a extensão — superutilizador, OU versão por omissão trusted + CREATE na base atual + CREATE no schema extensions (exigência conservadora). Camadas da plataforma (ex.: lista de extensões permitidas) não são visíveis no catálogo'::text, ((SELECT estado FROM est) = 'INSTALADA' OR coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR (coalesce((SELECT trusted FROM ua), false) AND has_database_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), current_database(), 'CREATE') AND has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'extensions', 'CREATE')))::boolean, 'sim (NOVA) · n.a. (INSTALADA)'::text, (CASE WHEN (SELECT estado FROM est) = 'INSTALADA' THEN 'n.a. (INSTALADA)' ELSE 'super=' || coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false)::text || ' trusted=' || coalesce((SELECT trusted::text FROM ua), 'n/d') || ' CREATE base=' || coalesce(has_database_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), current_database(), 'CREATE')::text, 'NULL') || ' CREATE extensions=' || coalesce(has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'extensions', 'CREATE')::text, 'NULL') END)::text
  UNION ALL SELECT 'P02-14'::text, 'só NOVA (n.a. se INSTALADA): nenhum privilégio por omissão global do dono histórico NEM do superutilizador de arranque (lido como dono de pg_catalog, sem supor o OID 10) retira EXECUTE a PUBLIC e a service_role nas funções que a extensão vai criar'::text, ((SELECT estado FROM est) = 'INSTALADA' OR ((SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_default_acl d WHERE d.defaclobjtype = 'f' AND d.defaclnamespace = 0 AND d.defaclrole IN ((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), (SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog')) AND NOT EXISTS (SELECT 1 FROM aclexplode(d.defaclacl) e WHERE e.privilege_type = 'EXECUTE' AND (e.grantee = 0 OR e.grantee = (SELECT oid FROM pg_roles WHERE rolname = 'service_role'))))))::boolean, 'nenhum (NOVA) · n.a. (INSTALADA)'::text, (CASE WHEN (SELECT estado FROM est) = 'INSTALADA' THEN 'n.a. (INSTALADA)' WHEN (SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog') IS NULL THEN 'superutilizador de arranque não identificado' WHEN EXISTS (SELECT 1 FROM pg_default_acl d WHERE d.defaclobjtype = 'f' AND d.defaclnamespace = 0 AND d.defaclrole IN ((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), (SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog')) AND NOT EXISTS (SELECT 1 FROM aclexplode(d.defaclacl) e WHERE e.privilege_type = 'EXECUTE' AND (e.grantee = 0 OR e.grantee = (SELECT oid FROM pg_roles WHERE rolname = 'service_role')))) THEN 'há privilégios por omissão que retiram EXECUTE' ELSE 'nenhum (arranque=' || pg_get_userbyid((SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog')) || ')' END)::text
  UNION ALL SELECT 'P02-15'::text, 'dono histórico com USAGE em extensions (o S4-01 cria public.text_norm, que referencia extensions.unaccent)'::text, (coalesce((SELECT rolsuper FROM pg_roles WHERE oid = (SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles'))), false) OR has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'extensions', 'USAGE'))::boolean, 'sim'::text, (coalesce(has_schema_privilege((SELECT c.relowner FROM pg_class c WHERE c.oid = to_regclass('public.user_roles')), 'extensions', 'USAGE')::text, 'NULL'))::text
  UNION ALL SELECT 'P02-16'::text, 'só INSTALADA (n.a. se NOVA): o dicionário extensions.unaccent pertence à extensão, usa o modelo extensions.unaccent (init/lexize de extensions, também da extensão), tem as opções do script da extensão (RULES = ''unaccent'') e o mesmo dono que extensions.unaccent(regdictionary, text), que é o dono da extensão ou o superutilizador de arranque'::text, ((SELECT estado FROM est) = 'NOVA' OR ((SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent') IS NOT NULL AND (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_ts_dict'::regclass AND d.objid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent') AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e') AND EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_ts_template'::regclass AND d.objid = (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent') AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e') AND (SELECT dicttemplate FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')) = (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent') AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE p.oid = (SELECT tmplinit FROM pg_ts_template WHERE oid = (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent')) AND n.nspname = 'extensions' AND p.proname = 'unaccent_init') AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE p.oid = (SELECT tmpllexize FROM pg_ts_template WHERE oid = (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent')) AND n.nspname = 'extensions' AND p.proname = 'unaccent_lexize') AND lower(regexp_replace(coalesce((SELECT dictinitoption FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')), ''), '\s', '', 'g')) = 'rules=''unaccent''' AND (SELECT dictowner FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')) = (SELECT proowner FROM pg_proc WHERE oid = to_regprocedure('extensions.unaccent(regdictionary, text)')) AND (SELECT dictowner FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')) IN ((SELECT extowner FROM pg_extension WHERE oid = (SELECT oid FROM ux)), (SELECT n.nspowner FROM pg_namespace n WHERE n.nspname = 'pg_catalog'))))::boolean, 'sim (INSTALADA) · n.a. (NOVA)'::text, (CASE WHEN (SELECT estado FROM est) = 'NOVA' THEN 'n.a. (NOVA)' ELSE 'dicionário=' || coalesce((SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')::text, 'em falta') || ' modelo=' || coalesce((SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent')::text, 'em falta') || ' membro=' || coalesce(EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_ts_dict'::regclass AND d.objid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent') AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e')::text, 'NULL') || '/' || coalesce(EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_ts_template'::regclass AND d.objid = (SELECT t.oid FROM pg_ts_template t JOIN pg_namespace n ON n.oid = t.tmplnamespace WHERE n.nspname = 'extensions' AND t.tmplname = 'unaccent') AND d.refclassid = 'pg_extension'::regclass AND d.refobjid = (SELECT oid FROM ux) AND d.deptype = 'e')::text, 'NULL') || ' opções=' || coalesce((SELECT dictinitoption FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent')), 'NULL') || ' dono=' || coalesce(pg_get_userbyid((SELECT dictowner FROM pg_ts_dict WHERE oid = (SELECT t.oid FROM pg_ts_dict t JOIN pg_namespace n ON n.oid = t.dictnamespace WHERE n.nspname = 'extensions' AND t.dictname = 'unaccent'))), 'NULL') || ' dono f()=' || coalesce(pg_get_userbyid((SELECT proowner FROM pg_proc WHERE oid = to_regprocedure('extensions.unaccent(regdictionary, text)'))), 'NULL') END)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 16 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO SÓ COMO DONO HISTÓRICO — o executor efetivo exige evidência independente (EXECUTOR-PRIVILEGES.md)'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
